using System.Text;
using System.Text.Json;
using IDCXray;
var count=0;
void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);count++;Console.WriteLine("PASS: "+name);}
const string fakeId="11111111-2222-3333-4444-555555555555";
var v=LinkParser.Parse($"vless://{fakeId}@example.com:443?security=reality&flow=xtls-rprx-vision&type=raw&sni=example.org&fp=chrome&pbk=FAKE_PUBLIC_KEY&sid=abcd#Fake");Check(v.Protocol=="vless"&&v.Network=="tcp"&&v.Flow=="xtls-rprx-vision","VLESS parsing and raw normalization");
var vmJson=JsonSerializer.Serialize(new{v="2",ps="Fake VMess",add="example.com",port="443",id=fakeId,aid="0",net="ws",host="example.com",path="/fake",tls="tls"});var vm=LinkParser.Parse("vmess://"+Convert.ToBase64String(Encoding.UTF8.GetBytes(vmJson)));Check(vm.Protocol=="vmess"&&vm.Network=="ws"&&vm.Port==443,"VMess parsing");
var tr=LinkParser.Parse("trojan://FAKE_PASSWORD@example.com:443?security=tls&type=grpc&serviceName=fake#Fake");Check(tr.Protocol=="trojan"&&tr.Network=="grpc"&&tr.Password=="FAKE_PASSWORD","Trojan parsing");
var ssAuth=Convert.ToBase64String(Encoding.UTF8.GetBytes("aes-128-gcm:FAKE_PASSWORD"));var ss=LinkParser.Parse($"ss://{ssAuth}@example.com:8388#Fake");Check(ss.Protocol=="shadowsocks"&&ss.Method=="aes-128-gcm"&&ss.Port==8388,"Shadowsocks parsing");
var sub=Convert.ToBase64String(Encoding.UTF8.GetBytes($"vless://{fakeId}@example.com:443#Fake\ntrojan://FAKE_PASSWORD@example.org:443#Other"));Check(SubscriptionDecoder.Decode(sub).Count==2,"Base64 subscription decoding");
var batch=LinkParser.ParseMany($"vless://{fakeId}@batch.example:443#Batch\nnot-a-link\ntrojan://FAKE_PASSWORD@batch2.example:443#Batch2");Check(batch.Nodes.Count==2&&batch.Errors.Count==1,"multi-link import skips malformed line");
var wg=LinkParser.Parse("wireguard://FAKE_PRIVATE@example.net:51820?publickey=FAKE_PUBLIC&address=10.0.0.2%2F32&allowedips=0.0.0.0%2F0&mtu=1380&keepalive=25#FakeWG");Check(wg.Protocol=="wireguard"&&wg.Port==51820&&wg.Mtu==1380&&wg.KeepAlive==25,"WireGuard share link parsing");
var managed=new List<Node>{new(){Protocol="vless",Host="same.example",Port=443,Name="Old",SubscriptionId="sub1"},new(){Protocol="trojan",Host="gone.example",Port=443,Name="Gone",Password="FAKE",SubscriptionId="sub1"},new(){Protocol="vless",Host="manual.example",Port=443,Name="Manual"},new(){Protocol="vless",Host="builtin.example",Port=443,Name="BuiltIn",IsBuiltInOracle=true}};
var sync=SubscriptionSynchronizer.Sync(managed,"sub1",new[]{new Node{Protocol="vless",Host="same.example",Port=443,Name="Updated",Id=fakeId},new Node{Protocol="ss",Host="new.example",Port=8388,Name="New",Method="aes-128-gcm",Password="FAKE"}});Check(sync.Added==1&&sync.Updated==1&&sync.Deleted==1&&managed.Any(n=>n.Name=="Updated")&&managed.Any(n=>n.Name=="Manual")&&managed.Any(n=>n.IsBuiltInOracle),"subscription sync add/update/delete preserves manual and built-in");
using var doc=JsonDocument.Parse(XrayConfig.Build(v));var root=doc.RootElement;Check(root.GetProperty("inbounds").GetArrayLength()==2&&root.GetProperty("outbounds")[0].GetProperty("protocol").GetString()=="vless","VLESS config generation");
using var td=JsonDocument.Parse(XrayConfig.Build(tr));using var sd=JsonDocument.Parse(XrayConfig.Build(ss));Check(td.RootElement.GetProperty("outbounds")[0].GetProperty("settings").GetProperty("servers")[0].TryGetProperty("password",out _)&&sd.RootElement.GetProperty("outbounds")[0].GetProperty("settings").GetProperty("servers")[0].TryGetProperty("method",out _),"Trojan and Shadowsocks config shapes");
var fakeNode=new Node{Protocol="vless",Host="fake.example",Port=443,Id=fakeId,Name="Test"};
using var aiDoc=JsonDocument.Parse(XrayConfig.BuildAiOnly(fakeNode,10808,10809,"Global",false,new[]{new RouteRule("domain","outside.example","proxy")}));
var aiRoot=aiDoc.RootElement;var aiRules=aiRoot.GetProperty("routing").GetProperty("rules");
var allowed=new HashSet<string>(new[]{"geosite:cloudflare","geosite:openai","geosite:anthropic","geosite:google","geosite:google-gemini","geosite:google-deepmind","domain:chatgpt.com","domain:claude.ai","domain:cloudflare.com"});
var aiProxy=aiRules.EnumerateArray().Single(r=>r.GetProperty("outboundTag").GetString()=="proxy");var aiDomains=aiProxy.GetProperty("domain").EnumerateArray().Select(x=>x.GetString()!).ToHashSet();
Check(allowed.IsSubsetOf(aiDomains)&&aiDomains.Contains("domain:accounts.google.com")&& !aiDomains.Contains("domain:outside.example"),"AI-only fixed service allowlist ignores mode, toggle, and custom rules");
Check(aiRoot.GetProperty("inbounds").EnumerateArray().All(i=>i.GetProperty("sniffing").GetProperty("enabled").GetBoolean()&&new[]{"http","tls","quic"}.All(x=>i.GetProperty("sniffing").GetProperty("destOverride").EnumerateArray().Any(d=>d.GetString()==x))),"AI-only SOCKS and HTTP sniffing");
var lastAiRule=aiRules[aiRules.GetArrayLength()-1];Check(aiRules[0].GetProperty("ip")[0].GetString()=="geoip:private"&&lastAiRule.GetProperty("network").GetString()=="tcp,udp"&&lastAiRule.GetProperty("outboundTag").GetString()=="direct","AI-only private bypass and final TCP/UDP direct catch-all");
Check(aiRoot.GetProperty("outbounds")[0].GetProperty("tag").GetString()=="direct"&&!aiRules.EnumerateArray().Any(r=>r.GetProperty("outboundTag").GetString()=="proxy"&&!r.TryGetProperty("domain",out _))&&!aiDomains.Contains("geosite:category-ai-!cn"),"AI-only never defaults all traffic to proxy");
var us=BuiltInDefaults.CreateUsNode();Check(us.Protocol=="vless"&&us.Host==BuiltInDefaults.UsHost&&us.Port==BuiltInDefaults.UsPort&&us.Network=="tcp"&&us.Security=="reality"&&us.Sni=="swdist.apple.com"&&us.Fingerprint=="chrome"&&us.Flow=="xtls-rprx-vision"&&!us.IsBuiltInOracle&&!string.IsNullOrWhiteSpace(us.Id)&&!string.IsNullOrWhiteSpace(us.PublicKey),"US built-in node shape");
Console.WriteLine($"All {count} unit checks passed.");
